 "content": "from math import gcd
from functools import reduce


def _runs(values):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == 8:
            j = i + 1
            while j < len(values) and values[j] == 8:
                j += 1
            runs.append(j - i)
            i = j
        else:
            i += 1
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in eight), max(r for r, c in eight)
    c0, c1 = min(c for r, c in eight), max(c for r, c in eight)

    lengths = []
    for r in range(r0, r1 + 1):
        lengths += _runs(grid[r][c0:c1 + 1])
    for c in range(c0, c1 + 1):
        lengths += _runs([grid[r][c] for r in range(r0, r1 + 1)])
    unit = reduce(gcd, lengths)
    mh, mw = (r1 - r0 + 1) // unit, (c1 - c0 + 1) // unit

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    mr0, mc0 = min(r for r, c, v in markers), min(c for r, c, v in markers)
    mr1, mc1 = max(r for r, c, v in markers), max(c for r, c, v in markers)
    mh0, mw0 = (mr1 - mr0 + 1), (mc1 - mc0 + 1)

    # The compact colored key is rotated clockwise onto the block-shaped 8 figure.
    out = [row[:] for row in grid]
    for r, c, color in markers:
        kr, kc = r - mr0, c - mc0
        tr, tc = kc, mh0 - 1 - kr
        if tr >= mh or tc >= mw:
            continue
        for dr in range(unit):
            for dc in range(unit):
                rr, cc = r0 + tr * unit + dr, c0 + tc * unit + dc
                if rr <= r1 and cc <= c1 and grid[rr][cc] == 8:
                    out[rr][cc] = color
    return out
